package net.civeira.phylax.features.notification.smtpoutboundconfig.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class RetryDelayVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property retry delay of smtp outbound config ")
  void test_retry_delay_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> RetryDelayVO.tryFrom(null));
    Assertions.assertEquals(1, RetryDelayVO.from(1).getRetryDelay());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> RetryDelayVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + 1 + "]", RetryDelayVO.from(1).toString());
  }
}
